add(H2("7.6 Sensitivity analysis"));
add(P("Figure 7 varies the false-alarm budget δ. On S1 the results are almost flat over two orders of magnitude (LCE 0.031 to 0.028, width within 0.2%). On MachineTemp larger budgets trade more alarms (47 at δ = 0.001, 94 at δ = 0.1) for somewhat narrower intervals and lower LCE. On the stationary stream an alarm appears in 1 of 10 runs only when δ ≥ 0.05, as the guarantee predicts. The window size W ∈ {250, 500, 1000} changes width by about 1% or less on both S1 and MachineTemp. Table 8 varies the target level. The width reductions on MachineTemp persist at α = 0.05 (7.54 to 5.88, −21.9%) and α = 0.2 (3.92 to 3.32, −15.4%), ELEC2 LCE improves at every α, and nominal coverage is maintained within 0.002 in all 12 cases."));
add(FIG(__dirname + "/../figures/fig7_sensitivity.png", 4320, 1440, "**Fig. 7** Sensitivity of MARS(ACI) to the false-alarm budget δ: LCE (left), width relative to δ = 0.01 (middle), and alarms per run on the stationary stream S3 (right; 10 seeds)"));
